-- This embedded migration is the sole schema owner; runtime never calls EF migration APIs.
DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname = 'access') THEN
        CREATE SCHEMA access;
    END IF;
END $EF$;


CREATE TABLE access.identity_roles (
    "Id" text NOT NULL,
    "Name" character varying(256),
    "NormalizedName" character varying(256),
    "ConcurrencyStamp" text,
    CONSTRAINT "PK_identity_roles" PRIMARY KEY ("Id")
);


CREATE TABLE access.users (
    id text NOT NULL,
    "DisplayName" character varying(120) NOT NULL,
    "IsActive" boolean NOT NULL,
    "UserName" character varying(256),
    "NormalizedUserName" character varying(256),
    "Email" character varying(256),
    "NormalizedEmail" character varying(256),
    "EmailConfirmed" boolean NOT NULL,
    "PasswordHash" text,
    "SecurityStamp" text,
    "ConcurrencyStamp" text,
    "PhoneNumber" text,
    "PhoneNumberConfirmed" boolean NOT NULL,
    "TwoFactorEnabled" boolean NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "LockoutEnabled" boolean NOT NULL,
    "AccessFailedCount" integer NOT NULL,
    CONSTRAINT "PK_users" PRIMARY KEY (id)
);


CREATE TABLE access.identity_role_claims (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "RoleId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_identity_role_claims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_identity_role_claims_identity_roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES access.identity_roles ("Id") ON DELETE CASCADE
);


CREATE TABLE access.identity_user_claims (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" text NOT NULL,
    "ClaimType" text,
    "ClaimValue" text,
    CONSTRAINT "PK_identity_user_claims" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_identity_user_claims_users_UserId" FOREIGN KEY ("UserId") REFERENCES access.users (id) ON DELETE CASCADE
);


CREATE TABLE access.identity_user_logins (
    "LoginProvider" text NOT NULL,
    "ProviderKey" text NOT NULL,
    "ProviderDisplayName" text,
    "UserId" text NOT NULL,
    CONSTRAINT "PK_identity_user_logins" PRIMARY KEY ("LoginProvider", "ProviderKey"),
    CONSTRAINT "FK_identity_user_logins_users_UserId" FOREIGN KEY ("UserId") REFERENCES access.users (id) ON DELETE CASCADE
);


CREATE TABLE access.identity_user_roles (
    "UserId" text NOT NULL,
    "RoleId" text NOT NULL,
    CONSTRAINT "PK_identity_user_roles" PRIMARY KEY ("UserId", "RoleId"),
    CONSTRAINT "FK_identity_user_roles_identity_roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES access.identity_roles ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_identity_user_roles_users_UserId" FOREIGN KEY ("UserId") REFERENCES access.users (id) ON DELETE CASCADE
);


CREATE TABLE access.identity_user_tokens (
    "UserId" text NOT NULL,
    "LoginProvider" text NOT NULL,
    "Name" text NOT NULL,
    "Value" text,
    CONSTRAINT "PK_identity_user_tokens" PRIMARY KEY ("UserId", "LoginProvider", "Name"),
    CONSTRAINT "FK_identity_user_tokens_users_UserId" FOREIGN KEY ("UserId") REFERENCES access.users (id) ON DELETE CASCADE
);


CREATE INDEX "IX_identity_role_claims_RoleId" ON access.identity_role_claims ("RoleId");


CREATE UNIQUE INDEX "RoleNameIndex" ON access.identity_roles ("NormalizedName");


CREATE INDEX "IX_identity_user_claims_UserId" ON access.identity_user_claims ("UserId");


CREATE INDEX "IX_identity_user_logins_UserId" ON access.identity_user_logins ("UserId");


CREATE INDEX "IX_identity_user_roles_RoleId" ON access.identity_user_roles ("RoleId");


CREATE UNIQUE INDEX "EmailIndex" ON access.users ("NormalizedEmail");


CREATE UNIQUE INDEX "UserNameIndex" ON access.users ("NormalizedUserName");



CREATE TABLE access.organizations (
    id uuid PRIMARY KEY,
    name text NOT NULL CHECK (length(name) BETWEEN 1 AND 120),
    slug text NOT NULL UNIQUE CHECK (length(slug) BETWEEN 1 AND 64 AND slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
    created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE access.memberships (
    organization_id uuid NOT NULL REFERENCES access.organizations(id),
    user_id text NOT NULL REFERENCES access.users(id),
    role text NOT NULL CHECK (role IN ('owner','editor','viewer')),
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (organization_id,user_id)
);
CREATE INDEX memberships_user_idx ON access.memberships(user_id);
CREATE TABLE access.sessions (
    id uuid PRIMARY KEY,
    user_id text NOT NULL REFERENCES access.users(id),
    security_stamp text NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    revoked_at timestamptz NULL
);
CREATE INDEX sessions_user_idx ON access.sessions(user_id);
